+      color: var(--text);
+      background:
+        radial-gradient(circle at top, rgba(124, 156, 255, 0.16), transparent 34%),
+        linear-gradient(180deg, #08101d 0%, var(--bg) 100%);
+    }
+
+    main {
+      width: min(100%, 520px);
+    }
+
+    .card {
+      padding: 32px;
+      border: 1px solid var(--panel-border);
+      border-radius: var(--radius);
+      background: rgba(17, 26, 45, 0.94);
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(10px);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.5rem, 2vw, 1.9rem);
+      line-height: 1.2;
+      letter-spacing: -0.02em;
+    }
+
+    .lede {
+      margin: 0 0 24px;
+      color: var(--muted);
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 10px;
+      padding: 18px;
+      border: 1px solid #273654;
+      border-radius: 16px;
+      background: rgba(9, 15, 27, 0.56);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 12px;
+    }
+
+    input[type="checkbox"] {
+      width: 1.15rem;
+      height: 1.15rem;
+      margin: 0;
+      flex: 0 0 auto;
+      accent-color: var(--accent);
+    }
+
+    label {
+      color: var(--text);
+      cursor: pointer;
+      font-weight: 600;
+    }
+
+    .required-mark {
+      color: var(--accent-strong);
+    }
+
+    .help-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.95rem;
+      padding-left: calc(1.15rem + 12px);
+    }
+
+    .error-text {
+      margin: 0;
+      color: var(--error);
+      font-size: 0.95rem;
+      padding-left: calc(1.15rem + 12px);
+    }
+
+    button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 0.9rem 1.3rem;
+      font: inherit;
+      font-weight: 700;
+      color: #09111f;
+      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
+      box-shadow: 0 12px 30px rgba(124, 156, 255, 0.28);
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.05);
+    }
+
+    :focus-visible {
+      outline: 3px solid #d7e2ff;
+      outline-offset: 3px;
+    }
+
+    button:focus-visible {
+      outline-offset: 4px;
+    }
+
+    .status {
+      min-height: 1.5em;
+      margin: 0;
+      color: var(--accent-strong);
+      font-weight: 600;
+    }
+
+    @media (max-width: 480px) {
+      .card {
+        padding: 22px;
+      }
+
+      .form-field {
+        padding: 14px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="card" aria-labelledby="page-title">
+      <h1 id="page-title">Consent to the Terms of Use</h1>
+      <p class="lede">Please review and confirm your agreement before continuing.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="agree-terms"
+              name="agree-terms"
+              type="checkbox"
+              required
+              aria-describedby="agree-help agree-error">
+            <label for="agree-terms">
+              I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
+            </label>
+          </div>
+
+          <p id="agree-help" class="help-text">You must agree to continue.</p>
+          <p id="agree-error" class="error-text" hidden>Error: Please agree to the Terms of Use.</p>
+        </div>
+
+        <button type="submit">Continue</button>
+        <p id="form-status" class="status" aria-live="polite"></p>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.getElementById('consent-form');
+    const checkbox = document.getElementById('agree-terms');
+    const errorText = document.getElementById('agree-error');
+    const statusText = document.getElementById('form-status');
+
+    function setCheckboxError(isInvalid) {
+      checkbox.setAttribute('aria-invalid', String(isInvalid));
+      errorText.hidden = !isInvalid;
+    }
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      if (!checkbox.checked) {
+        setCheckboxError(true);
+        statusText.textContent = '';
+        checkbox.focus();
+        return;
+      }
+
+      setCheckboxError(false);
+      statusText.textContent = 'Consent recorded. You can now continue.';
+    });
+
+    checkbox.addEventListener('change', () => {
+      if (checkbox.checked) {
+        setCheckboxError(false);
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
